parameters.inputSchema:
{
  "type": "object",
  "required": [
    "speak",
    "action",
    "state",
    "intent"
  ],
  "properties": {
    "speak": {
      "type": "string",
      "description": "What is read aloud to the caller, in the session language, under 45 words"
    },
    "action": {
      "type": "string",
      "enum": [
        "continue",
        "handoff",
        "end"
      ]
    },
    "state": {
      "type": "string",
      "enum": [
        "IDENTIFY",
        "CONSENT",
        "NEED",
        "DEALER",
        "SERVICES",
        "SLOT",
        "CONFIRM",
        "BOOKED",
        "LOOKUP",
        "CONFIRM_CANCEL",
        "CANCELLED",
        "MOVED",
        "CALLBACK",
        "CALLBACK_LOGGED",
        "SELF_SERVICE",
        "WRAPUP",
        "HANDOFF"
      ]
    },
    "intent": {
      "type": "string",
      "enum": [
        "BOOK",
        "RESCHEDULE",
        "CANCEL",
        "CALLBACK",
        "SELF_SERVICE",
        "OTHER",
        "UNKNOWN"
      ]
    },
    "handoffReason": {
      "type": [
        "string",
        "null"
      ],
      "enum": [
        "CALLER_REQUEST",
        "SCENARIO_REQUIRES_AGENT",
        "NOT_UNDERSTOOD",
        "BACKEND_UNAVAILABLE",
        "IDENTIFICATION_FAILED",
        "NO_SLOT",
        "POLICY",
        "PLATFORM_ERROR",
        null
      ]
    },
    "slotId": {
      "type": [
        "string",
        "null"
      ],
      "description": "In state CONFIRM: the slotId of the option being read back to the caller (new booking or move). Otherwise null."
    },
    "confidence": {
      "type": "number",
      "minimum": 0,
      "maximum": 1
    },
    "summary": {
      "type": "string",
      "description": "One sentence for a human agent: what the caller wants and where the conversation is"
    }
  }
}
